    pg.add_script_tag(path=S+'/tests/t8/seqprog.js')
    H="window.HYDRA"; P="window.HYDRA.plc"; L="window.HYDRA.plc.state"; SIM="window.HYDRA.designer.sim"; PM="window.HYDRA.plc.pmodel"; PN="window.HYDRA.plc.panel"
