    check('auto-build: six pages Main · Manual · Setpoints · Alarms · I/O · Trends', pages==['Main','Manual','Setpoints','Alarms','I/O','Trends'], pages)
    check('auto-build: E-stop, START/STOP/RESET, mode, tower, step chain, cylinders, valves, gauge, trend, jogs, recipe, alarm list', {'estop','pushbutton','selector','tower','stepchain','cylinder','valve','gauge','trend','jog','recipe','alarmlist','ioleds','motor','production'}<=types, types)
