    check('auto-build adds the panel variables (Mode, jog per cylinder)', 'Mode' in vars_ and 'Jog_1A1_plus' in vars_ and 'Jog_2A1_minus' in vars_, vars_)
    check('every auto-built binding exists', ev(f"{PN}.allIssues({H}.S.project.value,'{pid}').length")==0, ev(f"{PN}.allIssues({H}.S.project.value,'{pid}').map(x=>x.text)"))
    st=ev(f"(()=>{{const pn={H}.S.project.value.programs['{pid}'].panel; return pn.widgets.find(w=>w.type==='pushbutton'&&w.p.label==='START').p}})()")
