    check('header shows MANUAL', 'MANUAL' in pg.inner_text('.op-ph'))
    stb=pg.query_selector('.opn .op-pb[data-act^="in:"]'); check('START disabled outside AUTO (enabled when Mode = AUTO)', 'dis' in stb.get_attribute('class') and 'AUTO' in (stb.get_attribute('title') or ''), stb.get_attribute('title'))
    pg.click('.op-pt button:has-text("Manual")'); pg.wait_for_timeout(300)
