    jv2=ev(f"(()=>{{const pr={H}.S.project.value.programs['{pid}']; const v=pr.vars.find(x=>x.name==='Jog_1A1_plus'); return {L}.RT.value.rt.v[v.id]}})()")
    check('jog 1A1+ is hold-to-run in MANUAL (variable TRUE while held)', jv==True and jv2==False, (jv,jv2))
