    hs=pg.query_selector_all('.opn .op-2h'); a=hs[0].bounding_box(); bb=hs[1].bounding_box()
    ev("""(()=>{const h=[...document.querySelectorAll('.opn .op-2h')]; const ev=(el,t)=>el.dispatchEvent(new PointerEvent(t,{bubbles:true,pointerId:t.length+(el===h[0]?1:2)})); ev(h[0],'pointerdown'); ev(h[1],'pointerdown');})()"""); pg.wait_for_timeout(150)
    th=ev(f"(()=>{{const pr={H}.S.project.value.programs['{pid}']; const v=pr.vars.find(x=>x.name==='HMI_Step'); return {L}.RT.value.rt.v[v.id]}})()")
    ev("""(()=>{const h=[...document.querySelectorAll('.opn .op-2h')]; h[0].dispatchEvent(new PointerEvent('pointerup',{bubbles:true}));})()"""); pg.wait_for_timeout(150)
    th2=ev(f"(()=>{{const pr={H}.S.project.value.programs['{pid}']; const v=pr.vars.find(x=>x.name==='HMI_Step'); return {L}.RT.value.rt.v[v.id]}})()")
    check('two-hand: TRUE only while both are held (pressed within 0.5 s)', th==True and th2==False, (th,th2))
