    check('knob changes the relief valve setting live (0V1 → 120 bar)', abs(relief-120)<1e-6, relief)
    pg.click('.opn .t-recipe button:has-text("SAVE AS")'); pg.wait_for_timeout(300); pg.fill('.scrim input.in','Bracket A'); pg.click('.scrim button.primary'); pg.wait_for_timeout(300)
