    pg.mouse.move(hb['x']+5,hb['y']+5); pg.mouse.down(); pg.mouse.move(hb['x']+260,hb['y']+70, steps=6); pg.mouse.up(); pg.wait_for_timeout(300)
    w1=ev(f"(()=>{{const w={H}.S.project.value.programs['{pid}'].panel.widgets.find(w=>w.id==='{sel}'); return [w.w,w.h]}})()")
