    ev(f"window.HYDRA.plc.prt.editPanel('{pid}','t',p=>{{p.widgets.find(w=>w.id==='{sel}').p.src='sig:plc:gone'}})"); pg.wait_for_timeout(200)
    check('checks: a binding to a deleted part is reported', any('no longer exists' in x for x in ev(f"{PN}.allIssues({H}.S.project.value,'{pid}').map(x=>x.text)")))
